'use strict';

const nodeRequire = require;
const path = nodeRequire('path');
const MODULES = {
"""
post=r"""
};
const CACHE = Object.create(null);

function normalize(id, parentId) {
  if (!id.startsWith('.')) return id;
  const base = parentId ? path.posix.dirname(parentId) : '.';
  let resolved = path.posix.normalize(path.posix.join(base, id));
  if (!resolved.startsWith('.')) resolved = './' + resolved;
  if (!path.posix.extname(resolved)) resolved += '.js';
  return resolved;
}

function bridgeLoad(id, parentId) {
  const resolved = normalize(id, parentId);
  if (!Object.prototype.hasOwnProperty.call(MODULES, resolved)) {
    return nodeRequire(id);
  }
  if (CACHE[resolved]) return CACHE[resolved].exports;
  const mod = {exports: {}};
  CACHE[resolved] = mod;
  const filename = path.join(__dirname, '..', resolved.slice(2));
  const localRequire = request => {
    if (!request.startsWith('.')) return nodeRequire(request);
    return bridgeLoad(request, resolved);
  };
  localRequire.resolve = request => nodeRequire.resolve(request, {paths: [path.dirname(filename)]});
  MODULES[resolved](localRequire, mod, mod.exports, filename, path.dirname(filename));
  return mod.exports;
}

const core = bridgeLoad('./src/core.js');
Object.defineProperty(core, '__bridgeLoad', {value: bridgeLoad});
module.exports = core;

if (nodeRequire.main === module) {
  runHost().catch(error => {
    send({fatal: formatError(error)});
    process.exitCode = 1;
  });
}

const RESPONSE_PREFIX = '\x1eJSCODESHIFT:';
function send(value) {
  process.stdout.write(RESPONSE_PREFIX + JSON.stringify(value) + '\n');
}

function formatError(error) {
  const message = error && error.message ? error.message : String(error);
  if (!error || !error.stack) return message;
  const lines = error.stack.split('\n');
  const result = [];
  for (const line of lines) {
    if (line.includes(__filename)) break;
    result.push(line);
  }
  return `${message.replace(/\n/g, ' ')}\n${result.join('\n')}`;
}

async function runHost() {
  const readline = nodeRequire('readline');
  const transformPath = process.argv[2];
  const useBabel = process.argv[3] === 'babel';
  let transform;
  let parserFromTransform;

  if (useBabel) {
    let presetEnv;
    try { presetEnv = nodeRequire('@babel/preset-env'); } catch (_) {}
    const {DEFAULT_EXTENSIONS} = nodeRequire('@babel/core');
    const presets = [];
    if (presetEnv) presets.push([presetEnv.default, {targets: {node: true}}]);
    presets.push(/\.tsx?$/.test(transformPath)
      ? nodeRequire('@babel/preset-typescript').default
      : nodeRequire('@babel/preset-flow').default);
    nodeRequire('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        nodeRequire('@babel/plugin-transform-class-properties').default,
        nodeRequire('@babel/plugin-transform-nullish-coalescing-operator').default,
        nodeRequire('@babel/plugin-transform-optional-chaining').default,
        nodeRequire('@babel/plugin-transform-modules-commonjs').default,
        nodeRequire('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [/@babel\/parser/, /\/flow-parser\//, /\/recast\//, /\/ast-types\//],
    });
  }

  const loaded = nodeRequire(transformPath);
  transform = typeof loaded.default === 'function' ? loaded.default : loaded;
  if (loaded.parser) {
    parserFromTransform = typeof loaded.parser === 'string'
      ? bridgeLoad('./src/getParser.js')(loaded.parser)
      : loaded.parser;
  }

  const queue = [];
  let running = false;
  const rl = readline.createInterface({input: process.stdin, crlfDelay: Infinity});
  rl.on('line', line => {
    if (!line) return;
    queue.push(JSON.parse(line));
    drain();
  });

  async function drain() {
    if (running) return;
    running = true;
    while (queue.length) {
      const request = queue.shift();
      const stats = Object.create(null);
      const reports = [];
      try {
        const options = request.options || {};
        const parser = parserFromTransform || bridgeLoad('./src/getParser.js')(
          options.parser,
          options.parserConfig
        );
        const jscodeshift = core.withParser(parser);
        const out = await transform(
          {path: request.path, source: request.source},
          {
            j: jscodeshift,
            jscodeshift,
            stats(name, quantity) {
              if (!options.dry) return;
              quantity = typeof quantity === 'number' ? quantity : 1;
              stats[name] = (stats[name] || 0) + quantity;
            },
            report(message) { reports.push(String(message)); },
          },
          options
        );
        const status = !out ? 'skip' : out === request.source ? 'nochange' : 'ok';
        send({id: request.id, status, output: status === 'ok' ? out : null, stats, reports});
      } catch (error) {
        send({id: request.id, status: 'error', error: formatError(error), stats, reports});
      }
    }
    running = false;
  }
}
