{"command":"create","path":"/workspace/codebase/rust/main.rs","file_text":"use serde::{Deserialize, Serialize};
use serde_json::{Map, Number, Value};
use std::collections::{BTreeMap, HashSet};
use std::env;
use std::fs;
use std::io::{self, BufRead, BufReader, Read, Write};
use std::path::{Path, PathBuf};
use std::process::{Child, ChildStdin, ChildStdout, Command, Stdio};
use std::sync::{Arc, Mutex};
use std::thread;
use std::time::{Instant, SystemTime, UNIX_EPOCH};

const VERSION: &str = "17.4.0";
const DEFAULT_EXTENSIONS: &str = "cjs,es,es6,js,jsx,mjs,ts,tsx";
const PREFIX: &str = "\u{1e}JSCODESHIFT:";

#[derive(Default)]
struct Parsed {
    options: Map<String, Value>,
    paths: Vec<String>,
}

#[derive(Default, Clone, Serialize)]
#[serde(rename_all = "camelCase")]
struct Summary {
    error: usize,
    ok: usize,
    nochange: usize,
    skip: usize,
    stats: BTreeMap<String, f64>,
    time_elapsed: String,
}

#[derive(Serialize)]
struct Request<'a> {
    id: usize,
    path: &'a str,
    source: &'a str,
    options: &'a Map<String, Value>,
}

#[derive(Deserialize)]
struct Response {
    #[serde(default)]
    status: String,
    output: Option<String>,
    error: Option<String>,
    fatal: Option<String>,
    #[serde(default)]
    stats: BTreeMap<String, f64>,
    #[serde(default)]
    reports: Vec<String>,
}

fn main() {
    let args: Vec<String> = env::args().skip(1).collect();
    let parsed = match parse_args(&args) {
        Ok(value) => value,
        Err((code, message)) => {
            if code == 0 { print!("{message}"); } else { eprint!("{message}"); }
            std::process::exit(code);
        }
    };

    if parsed.paths.is_empty() && !bool_opt(&parsed.options, "stdin") {
        eprint!("Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}", help_text());
        std::process::exit(1);
    }

    let mut paths = parsed.paths;
    if bool_opt(&parsed.options, "stdin") {
        let mut input = String::new();
        if let Err(error) = io::stdin().read_to_string(&mut input) {
            eprintln!("{error}");
            std::process::exit(1);
        }
        paths = input.split('\n').map(str::to_owned).collect();
    }

    let code = run(paths, parsed.options);
    std::process::exit(code);
}

fn defaults() -> Map<String, Value> {
    let mut options = Map::new();
    options.insert("transform".into(), Value::String("./transform.js".into()));
    options.insert("verbose".into(), Value::Number(0.into()));
    options.insert("dry".into(), Value::Bool(false));
    options.insert("print".into(), Value::Bool(false));
    options.insert("babel".into(), Value::Bool(true));
    options.insert("extensions".into(), Value::String(DEFAULT_EXTENSIONS.into()));
    options.insert("ignorePattern".into(), Value::Array(vec![]));
    options.insert("ignoreConfig".into(), Value::Array(vec![]));
    options.insert("gitignore".into(), Value::Bool(false));
    options.insert("runInBand".into(), Value::Bool(false));
    options.insert("silent".into(), Value::Bool(false));
    options.insert("parser".into(), Value::String("babel".into()));
    options.insert("failOnError".into(), Value::Bool(false));
    options.insert("stdin".into(), Value::Bool(false));
    options
}

fn option_key(name: &str) -> Option<(&'static str, bool, bool)> {
    let result = match name {
        "--transform" | "-t" => ("transform", false, false),
        "--cpus" | "-c" => ("cpus", false, false),
        "--verbose" | "-v" => ("verbose", false, false),
        "--dry" | "-d" | "--no-dry" => ("dry", true, false),
        "--print" | "-p" | "--no-print" => ("print", true, false),
        "--babel" | "--no-babel" => ("babel", true, false),
        "--extensions" => ("extensions", false, false),
        "--ignore-pattern" => ("ignorePattern", false, true),
        "--ignore-config" => ("ignoreConfig", false, true),
        "--gitignore" | "--no-gitignore" => ("gitignore", true, false),
        "--run-in-band" | "--no-run-in-band" => ("runInBand", true, false),
        "--silent" | "-s" | "--no-silent" => ("silent", true, false),
        "--parser" => ("parser", false, false),
        "--parser-config" => ("parserConfig", false, false),
        "--fail-on-error" | "--no-fail-on-error" => ("failOnError", true, false),
        "--stdin" | "--no-stdin" => ("stdin", true, false),
        _ => return None,
    };
    Some(result)
}

fn parse_args(args: &[String]) -> Result<Parsed, (i32, String)> {
    let mut result = Parsed { options: defaults(), paths: vec![] };
    let mut index = 0;
    while index < args.len() {
        let arg = &args[index];
        if !arg.starts_with('-') {
            result.paths.push(arg.clone());
            index += 1;
            continue;
        }
        let (name, inline) = match arg.find('=') {
            Some(position) => (&arg[..position], Some(arg[position + 1..].to_owned())),
            None => (arg.as_str(), None),
        };
        if name == "--help" || name == "-h" {
            return Err((0, help_text()));
        }
        if name == "--version" {
            return Err((0, version_text()));
        }

        if let Some((key, flag, list)) = option_key(name) {
            if flag {
                let value = if name.starts_with("--no-") {
                    false
                } else if let Some(value) = inline {
                    value == "1"
                } else {
                    true
                };
                result.options.insert(key.into(), Value::Bool(value));
            } else {
                let value = if let Some(value) = inline {
                    value
                } else if index + 1 < args.len() && !args[index + 1].starts_with('-') {
                    index += 1;
                    args[index].clone()
                } else {
                    return Err((1, format!("Missing value: --{} requires a value\n\n---\n\n{}", long_name(key), help_text())));
                };
                let processed = process_known(key, &value).map_err(|message| (1, message))?;
                if list {
                    result.options.get_mut(key).unwrap().as_array_mut().unwrap().push(processed);
                } else {
                    result.options.insert(key.into(), processed);
                }
            }
        } else {
            let key = name.trim_start_matches('-').strip_prefix("no-").unwrap_or(name.trim_start_matches('-'));
            let existed = result.options.contains_key(key);
            let mut value = inline;
            let is_flag = !existed && value.is_none() && index + 1 < args.len() && args[index + 1].starts_with('-');
            if is_flag {
                result.options.insert(key.into(), Value::Bool(true));
            } else {
                if value.is_none() && index + 1 < args.len() && !args[index + 1].starts_with('-') {
                    index += 1;
                    value = Some(args[index].clone());
                }
                let Some(value) = value else {
                    return Err((1, format!("Missing value: --{key} requires a value\n\n---\n\n{}", help_text())));
                };
                let value = parse_jsonish(&value);
                if existed && result.options.get(key) != Some(&Value::Bool(true)) {
                    let previous = result.options.remove(key).unwrap();
                    let mut values = match previous {
                        Value::Array(values) => values,
                        other => vec![other],
                    };
                    values.push(value);
                    result.options.insert(key.into(), Value::Array(values));
                } else {
                    result.options.insert(key.into(), value);
                }
            }
        }
        index += 1;
    }

    let parser = string_opt(&result.options, "parser");
    if !["babel", "babylon", "flow", "ts", "tsx"].contains(&parser.as_str()) {
        return Err((1, format!("Error: --parser must be one of the values babel,babylon,flow,ts,tsx\n\n---\n\n{}", help_text())));
    }
    let verbose = number_opt(&result.options, "verbose") as i64;
    if ![0, 1, 2].contains(&verbose) {
        return Err((1, format!("Error: --verbose must be one of the values 0,1,2\n\n---\n\n{}", help_text())));
    }
    Ok(result)
}

fn long_name(key: &str) -> &str {
    match key {
        "ignorePattern" => "ignore-pattern",
        "ignoreConfig" => "ignore-config",
        "runInBand" => "run-in-band",
        "parserConfig" => "parser-config",
        "failOnError" => "fail-on-error",
        other => other,
    }
}

fn process_known(key: &str, value: &str) -> Result<Value, String> {
    match key {
        "cpus" | "verbose" => {
            let number = value.parse::<f64>().unwrap_or(f64::NAN);
            Number::from_f64(number).map(Value::Number).ok_or_else(|| "Invalid number".to_owned())
        }
        "parserConfig" => {
            let contents = fs::read_to_string(value).map_err(|error| error.to_string())?;
            serde_json::from_str(&contents).map_err(|error| error.to_string())
        }
        _ => Ok(Value::String(value.to_owned())),
    }
}

fn parse_jsonish(value: &str) -> Value {
    serde_json::from_str(value).unwrap_or_else(|_| Value::String(value.to_owned()))
}

fn help_text() -> String {
    format!("Usage: jscodeshift [OPTION]... PATH...\n  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...\n  or:  jscodeshift [OPTION]... -t URL PATH...\n  or:  jscodeshift [OPTION]... --stdin < file_list.txt\n\nApply transform logic in TRANSFORM_PATH (recursively) to every PATH.\nIf --stdin is set, each line of the standard input is used as a path.\n\nOptions:\n\"...\" behind an option means that it can be supplied multiple times.\nAll options are also passed to the transformer, which means you can supply custom options that are not listed here.\n\n      --(no-)babel              apply babeljs to the transform file\n                                (default: true)\n  -c, --cpus=N                  start at most N child processes to process source files\n                                (default: max(all - 1, 1))\n  -d, --(no-)dry                dry run (no changes are made to files)\n                                (default: false)\n      --extensions=EXT          transform files with these file extensions (comma separated list)\n                                (default: {DEFAULT_EXTENSIONS})\n      --(no-)fail-on-error      Return a non-zero code when there are errors\n                                (default: false)\n  -h, --help                    print this help and exit\n      --ignore-config=FILE ...  ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)\n      --ignore-pattern=GLOB ...  ignore files that match a provided glob expression\n      --(no-)gitignore          adds entries the current directory's .gitignore file\n                                (default: false)\n      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files\n                                          (default: babel)\n      --parser-config=FILE      path to a JSON file containing a custom parser configuration for flow or babylon\n  -p, --(no-)print              print transformed files to stdout, useful for development\n                                (default: false)\n      --(no-)run-in-band        run serially in the current process\n                                (default: false)\n  -s, --(no-)silent             do not write to stdout or stderr\n                                (default: false)\n      --(no-)stdin              read file/directory list from stdin\n                                (default: false)\n  -t, --transform=FILE          path to the transform file. Can be either a local path or url\n                                (default: ./transform.js)\n  -v, --verbose=0|1|2           show more information about the transform process\n                                (default: 0)\n      --version                 print version and exit")
}

fn version_text() -> String {
    let script = "const p=n=>{const e=require.resolve(n);let d=require('path').dirname(e),r={};while(d!=='/'){try{const x=require(require('path').join(d,'package.json'));if(x.name===n){r=x;break}}catch(e){}d=require('path').dirname(d)}return r.version};console.log(require('@babel/core').version+'|'+p('@babel/parser')+'|'+p('flow-parser')+'|'+p('recast'))";
    let versions = Command::new("node").args(["-e", script]).current_dir(package_root()).output().ok()
        .and_then(|out| String::from_utf8(out.stdout).ok()).unwrap_or_default();
    let values: Vec<&str> = versions.trim().split('|').collect();
    if values.len() == 4 {
        format!("jscodeshift: {VERSION}\n - babel: {}\n - babylon: {}\n - flow: {}\n - recast: {}\n", values[0], values[1], values[2], values[3])
    } else {
        format!("jscodeshift: {VERSION}\n")
    }
}

fn run(paths: Vec<String>, mut options: Map<String, Value>) -> i32 {
    let start = Instant::now();
    let silent = bool_opt(&options, "silent");
    let verbose = number_opt(&options, "verbose") as i64;
    let mut transform = string_opt(&options, "transform");
    if transform.starts_with("http://") || transform.starts_with("https://") {
        match download_transform(&transform) {
            Ok(path) => transform = path.to_string_lossy().into_owned(),
            Err(error) => {
                eprintln!("{error}");
                return 1;
            }
        }
    } else {
        transform = match fs::canonicalize(&transform) {
            Ok(path) => path.to_string_lossy().into_owned(),
            Err(_) => {
                eprintln!("ERROR Transform file {transform} does not exist ");
                return 0;
            }
        };
    }
    options.insert("transform".into(), Value::String(transform.clone()));

    let patterns = match collect_patterns(&options) {
        Ok(patterns) => patterns,
        Err(error) => {
            eprintln!("{error}");
            return 1;
        }
    };
    let extensions: HashSet<String> = string_opt(&options, "extensions")
        .split(',').map(|value| format!(".{value}")).collect();
    let mut files = vec![];
    for path in paths {
        discover(Path::new(&path), &extensions, &patterns, &mut files);
    }

    if files.is_empty() {
        if !silent { println!("No files selected, nothing to do. "); }
        let summary = finish_summary(Summary::default(), start, silent);
        write_result(&summary);
        return 0;
    }

    let available = thread::available_parallelism().map(|n| n.get().saturating_sub(1).max(1)).unwrap_or(1);
    let requested = options.get("cpus").and_then(Value::as_f64).map(|n| n as usize).unwrap_or(available);
    let cpus = available.min(requested).max(1);
    let process_count = if bool_opt(&options, "runInBand") { 1 } else { files.len().min(cpus) };
    let chunk_size = if process_count > 1 { files.len().div_ceil(process_count).min(50) } else { files.len() };

    if !silent {
        println!("Processing {} files... ", files.len());
        if !bool_opt(&options, "runInBand") { println!("Spawning {process_count} workers..."); }
        if bool_opt(&options, "dry") { println!("Running in dry mode, no files will be written! "); }
    }

    let mut chunks = vec![];
    let mut offset = 0;
    while offset < files.len() {
        let end = (offset + chunk_size).min(files.len());
        if !silent && !bool_opt(&options, "runInBand") {
            println!("Sending {} files to free worker...", end - offset);
        }
        chunks.push(files[offset..end].to_vec());
        offset = end;
    }

    let shared_chunks = Arc::new(Mutex::new(chunks.into_iter()));
    let summary = Arc::new(Mutex::new(Summary::default()));
    let options = Arc::new(options);
    let mut handles = vec![];
    for _ in 0..process_count {
        let chunks = Arc::clone(&shared_chunks);
        let summary = Arc::clone(&summary);
        let options = Arc::clone(&options);
        let transform = transform.clone();
        handles.push(thread::spawn(move || {
            let mut worker = match Worker::start(&transform, bool_opt(&options, "babel")) {
                Ok(worker) => worker,
                Err(error) => {
                    eprintln!("{error}");
                    return;
                }
            };
            loop {
                let chunk = chunks.lock().unwrap().next();
                let Some(chunk) = chunk else { break };
                for file in chunk {
                    process_file(&mut worker, &file, &options, &summary, silent, verbose);
                }
            }
        }));
    }
    for handle in handles { let _ = handle.join(); }
    let summary = Arc::try_unwrap(summary).unwrap().into_inner().unwrap();
    let summary = finish_summary(summary, start, silent);
    write_result(&summary);
    if !silent && bool_opt(&options, "failOnError") && summary.error > 0 { 1 } else { 0 }
}

fn process_file(worker: &mut Worker, file: &str, options: &Map<String, Value>, summary: &Mutex<Summary>, silent: bool, verbose: i64) {
    let bytes = match fs::read(file) {
        Ok(bytes) => bytes,
        Err(error) => {
            record_status(summary, "error", file, Some(&format!("File error: {error}")), silent, verbose);
            return;
        }
    };
    let source = String::from_utf8_lossy(&bytes).into_owned();
    let response = match worker.process(file, &source, options) {
        Ok(response) => response,
        Err(error) => {
            record_status(summary, "error", file, Some(&format!("Transformation error ({error})")), silent, verbose);
            return;
        }
    };
    if let Some(fatal) = response.fatal {
        record_status(summary, "error", file, Some(&format!("Transformation error ({fatal})")), silent, verbose);
        return;
    }
    for report in response.reports {
        if !silent { println!(" REP {file} {report}"); }
    }
    {
        let mut current = summary.lock().unwrap();
        for (name, quantity) in response.stats {
            *current.stats.entry(name).or_insert(0.0) += quantity;
        }
    }
    match response.status.as_str() {
        "ok" => {
            let output = response.output.unwrap_or_default();
            if bool_opt(options, "print") { println!("{output}"); }
            if !bool_opt(options, "dry") {
                if let Err(error) = atomic_write(Path::new(file), output.as_bytes()) {
                    record_status(summary, "error", file, Some(&format!("File writer error: {error}")), silent, verbose);
                    return;
                }
            }
            record_status(summary, "ok", file, None, silent, verbose);
        }
        "nochange" => record_status(summary, "nochange", file, None, silent, verbose),
        "skip" => record_status(summary, "skip", file, None, silent, verbose),
        _ => record_status(summary, "error", file, Some(&format!("Transformation error ({})", response.error.unwrap_or_default())), silent, verbose),
    }
}

fn record_status(summary: &Mutex<Summary>, status: &str, file: &str, detail: Option<&str>, silent: bool, verbose: i64) {
    let mut value = summary.lock().unwrap();
    match status {
        "ok" => value.ok += 1,
        "nochange" => value.nochange += 1,
        "skip" => value.skip += 1,
        _ => value.error += 1,
    }
    drop(value);
    if silent { return; }
    let show = match status { "ok" => verbose >= 2, "nochange" | "skip" => verbose >= 1, _ => true };
    if show {
        let label = match status { "ok" => " OKK ", "nochange" => " NOC ", "skip" => " SKIP ", _ => " ERR " };
        if let Some(detail) = detail { println!("{label}{file} {detail}"); } else { println!("{label}{file}"); }
    }
}

fn finish_summary(mut summary: Summary, start: Instant, silent: bool) -> Summary {
    summary.time_elapsed = format!("{:.3}", start.elapsed().as_secs_f64());
    if !silent {
        println!("All done. ");
        println!("Results: \n{} errors\n{} unmodified\n{} skipped\n{} ok", summary.error, summary.nochange, summary.skip, summary.ok);
        if !summary.stats.is_empty() { println!("Stats: "); }
        for (name, value) in &summary.stats {
            if value.fract() == 0.0 { println!("{name}: {}", *value as i64); } else { println!("{name}: {value}"); }
        }
        println!("Time elapsed: {}seconds ", summary.time_elapsed);
    }
    summary
}

struct Worker {
    child: Child,
    input: ChildStdin,
    output: BufReader<ChildStdout>,
    next_id: usize,
}

impl Worker {
    fn start(transform: &str, babel: bool) -> Result<Self, String> {
        let host = package_root().join("bridge/transform-host.js");
        let mut child = Command::new("node")
            .arg(host).arg(transform).arg(if babel { "babel" } else { "no-babel" })
            .stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::inherit())
            .spawn().map_err(|error| error.to_string())?;
        let input = child.stdin.take().ok_or("Unable to open worker input")?;
        let output = BufReader::new(child.stdout.take().ok_or("Unable to open worker output")?);
        Ok(Self { child, input, output, next_id: 0 })
    }

    fn process(&mut self, path: &str, source: &str, options: &Map<String, Value>) -> Result<Response, String> {
        self.next_id += 1;
        serde_json::to_writer(&mut self.input, &Request { id: self.next_id, path, source, options }).map_err(|error| error.to_string())?;
        self.input.write_all(b"\n").and_then(|_| self.input.flush()).map_err(|error| error.to_string())?;
        loop {
            let mut line = String::new();
            let count = self.output.read_line(&mut line).map_err(|error| error.to_string())?;
            if count == 0 { return Err("Transform worker exited unexpectedly".into()); }
            if let Some(position) = line.find(PREFIX) {
                print!("{}", &line[..position]);
                let json = line[position + PREFIX.len()..].trim_end();
                return serde_json::from_str(json).map_err(|error| error.to_string());
            }
            print!("{line}");
        }
    }
}

impl Drop for Worker {
    fn drop(&mut self) {
        let _ = self.input.flush();
        let _ = self.child.kill();
        let _ = self.child.wait();
    }
}

fn discover(path: &Path, extensions: &HashSet<String>, patterns: &[String], files: &mut Vec<String>) {
    let display = path.to_string_lossy();
    let metadata = match fs::symlink_metadata(path) {
        Ok(metadata) => metadata,
        Err(_) => {
            eprintln!("Skipping path {display} which does not exist. ");
            return;
        }
    };
    if should_ignore(&display, patterns) { return; }
    if metadata.is_dir() {
        let entries = match fs::read_dir(path) {
            Ok(entries) => entries,
            Err(error) => { eprintln!("{error}"); return; }
        };
        for entry in entries {
            match entry {
                Ok(entry) => discover(&entry.path(), extensions, patterns, files),
                Err(_) => println!("Skipping path which does not exist."),
            }
        }
    } else {
        let extension = path.extension().map(|value| format!(".{}", value.to_string_lossy())).unwrap_or_default();
        if extensions.contains(&extension) { files.push(display.into_owned()); }
    }
}

fn collect_patterns(options: &Map<String, Value>) -> Result<Vec<String>, String> {
    let mut patterns = vec![];
    if let Some(values) = options.get("ignorePattern").and_then(Value::as_array) {
        for value in values.iter().filter_map(Value::as_str) { add_pattern(value, &mut patterns); }
    }
    let mut configs: Vec<String> = options.get("ignoreConfig").and_then(Value::as_array).into_iter().flatten()
        .filter_map(Value::as_str).map(str::to_owned).collect();
    if bool_opt(options, "gitignore") { configs.push(".gitignore".into()); }
    for config in configs {
        let content = fs::read_to_string(config).map_err(|error| error.to_string())?;
        for line in content.lines() { add_pattern(line, &mut patterns); }
    }
    Ok(patterns)
}

fn add_pattern(value: &str, patterns: &mut Vec<String>) {
    if value.is_empty() || value.starts_with('#') { return; }
    if !value.contains('/') { patterns.push(format!("**/{value}")); }
    else if value.ends_with('/') {
        patterns.push(format!("**/{value}**"));
        patterns.push(format!("{value}**"));
    }
    patterns.push(value.to_owned());
}

fn should_ignore(path: &str, patterns: &[String]) -> bool {
    let path = path.replace('\\', "/");
    let normalized = path.trim_start_matches("../").trim_start_matches("./");
    patterns.iter().any(|pattern| glob_match(pattern, &path) || (normalized != path && glob_match(pattern, normalized)))
}

fn glob_match(pattern: &str, text: &str) -> bool {
    let p = pattern.as_bytes();
    let t = text.as_bytes();
    let mut memo = vec![vec![None; t.len() + 1]; p.len() + 1];
    fn go(p: &[u8], t: &[u8], i: usize, j: usize, memo: &mut [Vec<Option<bool>>]) -> bool {
        if let Some(value) = memo[i][j] { return value; }
        let value = if i == p.len() { j == t.len() }
        else if p[i] == b'*' {
            let double = i + 1 < p.len() && p[i + 1] == b'*';
            if double {
                let next = i + 2;
                (next < p.len() && p[next] == b'/' && go(p, t, next + 1, j, memo))
                    || go(p, t, next, j, memo)
                    || (j < t.len() && go(p, t, i, j + 1, memo))
            } else {
                go(p, t, i + 1, j, memo) || (j < t.len() && t[j] != b'/' && go(p, t, i, j + 1, memo))
            }
        } else if j < t.len() && (p[i] == b'?' && t[j] != b'/' || p[i] == t[j]) {
            go(p, t, i + 1, j + 1, memo)
        } else { false };
        memo[i][j] = Some(value);
        value
    }
    go(p, t, 0, 0, &mut memo)
}

fn atomic_write(path: &Path, bytes: &[u8]) -> io::Result<()> {
    let parent = path.parent().unwrap_or_else(|| Path::new("."));
    let nonce = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos();
    let temp = parent.join(format!(".jscodeshift-{}-{nonce}.tmp", std::process::id()));
    let permissions = fs::metadata(path).ok().map(|metadata| metadata.permissions());
    let result = (|| {
        let mut file = fs::File::create(&temp)?;
        file.write_all(bytes)?;
        file.sync_all()?;
        if let Some(permissions) = permissions { fs::set_permissions(&temp, permissions)?; }
        fs::rename(&temp, path)
    })();
    if result.is_err() { let _ = fs::remove_file(&temp); }
    result
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let extension = Path::new(url).extension().and_then(|value| value.to_str()).unwrap_or("js");
    let path = env::temp_dir().join(format!("jscodeshift{}-{}.{}", std::process::id(), SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default().as_nanos(), extension));
    let script = "const [u,p]=process.argv.slice(1),f=require('fs'),h=require(u.startsWith('https')?'https':'http');h.get(u,r=>{const s=f.createWriteStream(p);r.pipe(s);s.on('finish',()=>s.close())}).on('error',e=>{console.error(e.message);process.exit(1)})";
    let status = Command::new("node").args(["-e", script, url, &path.to_string_lossy()]).status().map_err(|error| error.to_string())?;
    if status.success() { Ok(path) } else { Err(format!("Unable to download transform {url}")) }
}

fn package_root() -> PathBuf {
    env::var_os("JSCODESHIFT_ROOT").map(PathBuf::from).unwrap_or_else(|| PathBuf::from(env!("CARGO_MANIFEST_DIR")))
}

fn bool_opt(options: &Map<String, Value>, key: &str) -> bool {
    options.get(key).and_then(Value::as_bool).unwrap_or(false)
}
fn string_opt(options: &Map<String, Value>, key: &str) -> String {
    options.get(key).and_then(Value::as_str).unwrap_or_default().to_owned()
}
fn number_opt(options: &Map<String, Value>, key: &str) -> f64 {
    options.get(key).and_then(Value::as_f64).unwrap_or(0.0)
}
fn write_result(summary: &Summary) {
    if let Some(path) = env::var_os("JSCODESHIFT_RESULT_FILE") {
        if let Ok(json) = serde_json::to_vec(summary) { let _ = fs::write(path, json); }
    }
}
