            }
        } else if j < t.len() && (p[i] == b'?' && t[j] != b'/' || p[i] == t[j]) {
            go(p, t, i + 1, j + 1, memo)
        } else { false };
        memo[i][j] = Some(value);
        value
    }
    go(p, t, 0, 0, &mut memo)
