function mapBundledFrame(line) {
  if (!line.includes(__filename)) return line;
  const match = line.match(/:(\d+):(\d+)\)?$/);
  if (!match) return null;
  const lineNumber = Number(match[1]);
  const range = moduleRanges.find(item => lineNumber > item.start && lineNumber <= item.end);
  if (!range) return null;
  const filename = path.join(__dirname, '..', range.id.slice(2));
  return line.replace(`${__filename}:${match[1]}:${match[2]}`, `${filename}:${lineNumber - range.start}:${match[2]}`);
